function lroute(string $name, array $parameters = [], ?string $locale = null): string
{
    $locale ??= app()->getLocale();

    return $locale === config('locales.default')
        ? route($name, $parameters)
        : route('localized.'.$name, ['locale' => $locale] + $parameters);
}

// lroute('tutor.schedule') → 영어면 /tutor/schedule, 한국어면 /ko/tutor/schedule

/**
 * 경로에 언어 접두사를 붙인 URL. lurl('/ai') → /ai(en) · /ko/ai(ko).
 * 메뉴처럼 라우트 이름이 아니라 경로로 적힌 링크에 쓴다.
 */
function lurl(string $path, ?string $locale = null): string
{
    $locale ??= app()->getLocale();

    return $locale === config('locales.default')
        ? url($path)
        : url('/'.$locale.($path === '/' ? '' : $path));
}

